import { useState, useEffect } from "react";
import InvoiceTable from "./InvoiceTable";

export interface Invoice {
  id: number;
  number: string;
  customer: string;
  amount: number;
  status: "paid" | "pending" | "overdue";
}

export const mockData: Invoice[] = [
  { id: 1, number: "INV-001", customer: "Acme Corp", amount: 1250.00, status: "paid" },
  { id: 2, number: "INV-002", customer: "Beta Solutions", amount: 890.50, status: "pending" },
  { id: 3, number: "INV-0-03", customer: "Nova Inc", amount: 2300.00, status: "overdue" },
  { id: 4, number: "INV-004", customer: "Global Tech", amount: 1500.00, status: "paid" },
  { id: 5, number: "INV-005", customer: "Alpha Dynamics", amount: 980.25, status: "pending" },
  { id: 6, number: "INV-006", customer: "Sunrise Co", amount: 3200.00, status: "overdue" },
  { id: 7, number: "INV-007", customer: "QuickStart Labs", amount: 1800.75, status: "paid" },
  { id: 8, number: "INV-008", customer: "Evergreen Systems", amount: 1450.00, status: "pending" },
];

export function App() {
  const [invoices, setInvoices] = useState<Invoice[]>(mockData);
  const [sortConfig, setSortConfig] = useState<{ key: keyof Invoice; direction: "ascending" | "descending" | null }>({
    key: "amount",
    direction: "descending",
  });

  useEffect(() => {
    const sortedInvoices = [...invoices].sort((a, b) => {
      if (a[sortConfig.key] < b[sortConfig.key]) {
        return sortConfig.direction === "ascending" ? -1 : 1;
      }
      if (a[sortConfig.key] > b[sortConfig.key]) {
        return sortConfig.direction === "ascending" ? 1 : -1;
      }
      return 0;
    });
    setInvoices(sortedInvoices);
  }, [sortConfig, invoices]);

  const handleSort = (key: keyof Invoice) => {
    setSortConfig((prev) => ({
      key,
      direction: prev.key === key && prev.direction === "ascending" ? "descending" : "ascending",
    }));
  };

  return (
    <div className="container mx-auto p-4 max-w-6xl">
      <h1 className="text-2xl font-bold mb-6 text-gray-800">Invoices</h1>
      <InvoiceTable
        invoices={invoices}
        onSort={handleSort}
        sortConfig={sortConfig}
      />
    </div>
  );
}
