```tsx
import { useState } from "react";
import { CheckIcon, ClockIcon, XIcon } from "lucide-react";

export interface Invoice {
  id: number;
  number: string;
  customer: string;
  amount: number;
  status: "paid" | "pending" | "overdue";
}

export interface TableSortConfig {
  key: keyof Invoice;
  direction: "ascending" | "descending" | null;
}

export function InvoiceTable({
  invoices,
  onSort,
  sortConfig,
}: {
  invoices: Invoice[];
  onSort: (key: keyof Invoice) => void;
  sortConfig: TableSortConfig;
}) {
  const getBadgeColor = (status: string) => {
    switch (status) {
      case "paid":
        return "bg-green-100 text-green-800";
      case "pending":
        return "bg-yellow-100 text-yellow-800";
      case "overdue":
        return "bg-red-100 text-red-800";
      default:
        return "bg-gray-100 text-gray-800";
    }
  };

  const renderStatusIcon = (status: string) => {
    switch (status) {
      case "paid":
        return <CheckIcon className="w-4 h-4" />;
      case "pending":
        return <ClockIcon className="w-4 h-4" />;
      case "overdue":
        return <XIcon className="w-4 h-4" />;
      default:
        return null;
    }
  };

  const renderStatusBadge = (status: string) => {
    return (
      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getBadgeColor(status)}`}>
        {renderStatusIcon(status)}
        <span className="ml-1">{status.charAt(0).toUpperCase() + status.slice(1)}</span>
      </span>
    );
  };

  const totalAmount = invoices.reduce((sum, invoice) => sum + invoice.amount, 0);

  return (
    <div className="overflow-x-auto">
      <table className="min-w-full border-collapse bg-white shadow rounded-lg overflow-hidden">
        <thead className="bg-gray-50">
          <tr>
            <th
              className="px-4 py-3 text-left text-sm font-semibold text-gray-700 border-b hover:bg-gray-100 cursor-pointer"
              onClick={() => onSort("amount")}
            >
              Amount
              {sortConfig.key === "amount" && (
                <span className="ml-1">
                  {sortConfig.direction === "ascending" ? "▲" : "▼"}
                </span>
              )}
            </th>
            <th
              className="px-4 py-3 text-left text-sm font-semibold text-gray-700 border-b hover:bg-gray-100 cursor-pointer"
              onClick={() => onSort("number")}
            >
              Number
            </th>
            <th
              className="px-4 py-3 text-left text-sm font-semibold text-gray-700 border-b hover:bg-gray-100 cursor-pointer"
              onClick={() => onSort("customer")}
            >
              Customer
            </th>
            <th
              className="px-4 py-3 text-left text-sm font-semibold text-gray-700 border-b hover:bg-gray-100 cursor-pointer"
              onClick={() => onSort("status")}
            >
              Status
            </th>
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-200">
          {invoices.map((invoice) => (
            <tr key={invoice.id} className="hover:bg-gray-50 transition-colors">
              <td className="px-4 py-3 text-sm font-medium text-gray-900">{invoice.amount.toFixed(2)}</td>
              <td className="px-4 py-3 text-sm text-gray-700">{invoice.number}</td>
              <td className="px-4 py-3 text-sm text-gray-700">{invoice.customer}</td>
              <td className="px-4 py-3 text-sm">
                {renderStatusBadge(invoice.status)}
              </td>
            </tr>
          ))}
        </tbody>
        <tfoot className="bg-gray-50 border-t">
          <tr>
            <td className="px-4 py-3 text-sm font-semibold text-gray-700" colSpan={3}>
              Total
            </td>
            <td className="px-4 py-3 text-sm font-semibold text-gray-700">
              {totalAmount.toFixed(2)}
            </td>
          </tr>
        </tfoot>
      </table>
    </div>
  );
}
